272	     * Return {@code base} if no other owner already uses it as a {@code customerCode}; otherwise
273	     * append {@code -<n>} with the smallest {@code n >= 2} that is not already taken, so distinct
274	     * owners always receive distinct customer codes.
275	     */
276	    private String deduplicateCustomerCode(String base, Owner owner) {
277	        Set<String> existing = ownerRepository.findAll().stream()
278	            .filter(other -> other != owner)
279	            .map(Owner::getCustomerCode)
280	            .filter(Objects::nonNull)
281	            .collect(Collectors.toSet());
282	        if (!existing.contains(base)) {
283	            return base;
284	        }
285	        int n = 2;
286	        while (existing.contains(base + "-" + n)) {
287	            n++;
288	        }
289	        return base + "-" + n;
290	    }
